class Solution {
public:
    int minimumScore(string s, string t) {
        int n = s.size(), m = t.size();
        vector<int> L(m + 1), R(m + 1);
        L[0] = -1;
        for (int i = 1; i <= m; i++) {
            if (L[i - 1] >= n) { L[i] = n; continue; }
            int k = L[i - 1] + 1;
            while (k < n && s[k] != t[i - 1]) k++;
            L[i] = (k < n) ? k : n;
        }
        R[m] = n;
        for (int j = m - 1; j >= 0; j--) {
            if (R[j + 1] <= -1) { R[j] = -2; continue; }
            int k = R[j + 1] - 1;
            while (k >= 0 && s[k] != t[j]) k--;
            R[j] = (k >= 0) ? k : -2;
        }
        int ans = m;
        int j = 0;
        for (int i = 0; i <= m; i++) {
            if (j < i) j = i;
            while (j <= m && L[i] >= R[j]) j++;
            if (j <= m) ans = min(ans, j - i);
        }
        return ans;
    }
};
